 {/* Load the Discord.js library */}
const Discord = require("discord.js");

{/* Create a new Discord client */}
const bot = new Discord.Client();

/* Set up event listener */
bot.on("ready", () => {
  console.log(`Logged in as ${bot.user.tag}`);
});

/* Handle message events */
bot.on("message", async (message) => {
  if (message.author.bot) return;

  /* Check if the message starts with "/"" */
  if (message.content.startsWith("/")) {
    const args = message.content.slice(1).split(" ");

    // If there's a command
    if (args[0] === "ping") {
      await message.channel.send("Pong!");
    } else if (args[0] === "status") {
      await message.channel.send("Status: Online");
    } else if (args[0] === "help") {
      await message.channel.send("Available commands:");
      await message.channel.send("- ping\n- status\n- help");
    }
  }
});

/* Log out when the bot is stopped */
bot.on("disconnect", () => {
  console.log("Bot disconnected.");
});

bot.login(process.env.BOT_TOKEN);

