public ResponseEntity<?> manager(
        @RequestParam("username") String username,
        @RequestParam("password") String password,
        @RequestParam("sortOrder") int sortOrder,
        @RequestParam("searchTerm") String searchTerm,
        @RequestParam("pageSize") Integer pageSize) {

    // GET FROM DB
    List<Item> items = itemRepository.findAll();
    List<InventoryItem> inventoryItems = inventoryItemService.findInventoryByUser(username);

    Map<String, Object> response = new HashMap<>();

    if (!password.equals("mysecretPassword")) {
        return ResponseEntity.status(401).body("Invalid Credentials");
    }

    if (items.isEmpty() && inventoryItems.isEmpty()) {
        return ResponseEntity.status(204).body("No items found");
    }

    // Applies sorting and pagination based on request
    if (sortOrder == 1) {
        items.sort((item1, item2) -> item2.getItemId().compareTo(item1.getItemId()));
    } else {
        items.sort((item1, item2) -> item1.getItemId().compareTo(item2.getItemId()));
    }

    Page<Item> paginatedItems = items.stream()
            .skip((int) (pageSize * sortOrder))
            .limit(pageSize)
            .collect(Collectors.toList());

    // Prepare the total number of items
    long totalPages = items.size() / pageSize;
    if (items.size() % pageSize != 0) {
        totalPages++;
    }

    // Sort values for the returned JSON
    Map<String, Object> dataMap = new HashMap<>();
    dataMap.put("items", paginatedItems);
    dataMap.put("totalPages", totalPages);

    if (itemRepository.count() > 0) {
        response.put("data", dataMap);
    } else {
        response.put("error", "No items available.");
    }

    return ResponseEntity.ok(response);
}

