function updateAppUI(rowIndex) {
    let item = JSONObject.total[rowIndex];
    let displayedItem = JSON.parse(JSON.stringify(item));
    const rowContainer = document.getElementById('rowContainer');
    const newDivElement = document.createElement('div');
    newDivElement.className = `row ${rowIndex}`;
    newDivElement.innerHTML = `
        <div class="col-md-1"><span>${rowIndex}</span></div>
        <div class="col-md-3">${displayedItem.section}</div>
        <div class="col-md-4">${displayedItem.signDate || ''}</div>
        <div class="col-md-1">${displayedItem.reasonLackingJSON || ''}</div>
        <div class="col-md-2">
            <input type="text" value="${displayedItem.weightFilterResultJSON || ''}" 
                   placeholder="Weight Filter Result"/>
        </div>
        <div class="col-md-1">
            <button onclick="toggleValidation(${rowIndex})">Validate</button>
        </div>
        <div class="col-md-1">
            <button onclick="copyToClipboard(${rowIndex})">Copy</button>
        </div>
    `;
    rowContainer.appendChild(newDivElement);
}

function toggleValidation(rowIndex) {
    // Grab the current row from array
    let item = JSONObject.total[rowIndex];
    console.log("item =", item); // debug
    let inputValue = JSON.parse(JSON.stringify(item)).weightFilterResultJSON;

    if (!inputValue) {
        alert("Please fill in the Weight Filter Result field.");
        return;
    }

    // Check If input matches expected format
    const regexMatch = /^[^0-9]+$/; // alphanumeric only
    if (!regexMatch.test(inputValue)) {
        alert("The Weight Filter Result must be alphanumeric only!");
        return;
    }

    // Detailed Error Check (optional)
    try {
        // Validate to ensure it's a string
        if (typeof inputValue !== 'string') {
            throw new Error("Must be a string");
        }

        // Extract the first two characters
        const firstTwoChars = inputValue.substring(0, 2);

        // Extract the last four characters
        const lastFourChars = inputValue.substring(inputValue.length - 4);

        // Segment with hyphen
        const hyphenSegment = inputValue.split('-')[1];

        // Normalize the remaining part
        const normalizedRemainingPart = inputValue.slice(2, -4).replace(/[^a-zA-Z]/g, '');

        // Optional validation: Ensure all parts are non-empty
        if (firstTwoChars.trim() === '') {
            throw new Error("First two characters cannot be empty");
        }
        if (lastFourChars.trim() === '') {
            throw new Error("Last four characters cannot be empty");
        }
        if (hyphenSegment.trim() === '') {
            throw new Error("Hyphen segment cannot be empty");
        }

        // Pass basic validation
        if (inputValue.trim().length >= 6 && inputValue.trim().length <= 16) {
            alert("Valid input format!");
            return;
        } else {
            alert("Input format is invalid. Please follow the correct pattern: XX-XXXXX-X where X represents any character.");
            return;
        }
    } catch (error) {
        alert(`Validation failed: ${error.message}`);
        return;
    }
}

function copyToClipboard(index) {
    let item = JSONObject.total[index];
    const text = JSON.stringify(item).replace(/\n/g, '').replace(/"/g, "'");
    navigator.clipboard.writeText(text).then(() => {
        alert("Copied to clipboard!");
    }).catch(err => {
        alert("Failed to copy to clipboard.");
    });
}

function initializeApp() {
    const index = Math.floor(Math.random() * JSONObject.total.length);
    updateAppUI(index);
}

document.addEventListener('DOMContentLoaded', function () {
    initializeApp();
});

