window.onload = function () {

  let ordersContainer = document.getElementById('orders-container');
  let orderDetails = [];

  // Example data for demonstration purposes
  const mockData = [
    { id: 1, customerId: 'C1', total: 189, status: 'complete' },
    { id: 2, customerId: 'C2', total: 327, status: 'processing' },
    { id: 3, customerId: 'C3', total: 64, status: 'cancelled' },
    { id: 4, customerId: 'C4', total: 249, status: 'completed' },
    { id: 5, customerId: 'C5', total: 88, status: 'pending' },
    { id: 6, customerId: 'C6', total: 568, status: 'delivered' },
    { id: 7, customerId: 'C7', total: 99, status: 'in transit' },
    { id: 8, customerId: 'C8', total: 66, status: 'returned' },
    { id: 9, customerId: 'C9', total: 77, status: 'redundant' },
    { id: 10, customerId: 'C10', total: 299, status: 'completed' }
  ];

  function displayOrders(orders) {
    orders.forEach(order => {
      let row = document.createElement('div');
      row.className = 'order-row';

      let statusClass = '';
      switch (order.status) {
        case 'complete':
          statusClass = 'status-completed';
          break;
        case 'processing':
          statusClass = 'status-processing';
          break;
        case 'cancelled':
          statusClass = 'status-cancelled';
          break;
        case 'completed':
          statusClass = 'status-completed';
          break;
        case 'pending':
          statusClass = 'status-pending';
          break;
        case 'delivered':
          statusClass = 'status-delivered';
          break;
        case 'in transit':
          statusClass = 'status-in-transit';
          break;
        case 'returned':
          statusClass = 'status-returned';
          break;
        case 'redundant':
          statusClass = 'status-redundant';
          break;
        default:
          statusClass = 'status-default';
      }

      row.innerHTML = `
        <div class="order-header">
          <span>${order.id}</span>
          <span>${order.customerId}</span>
          <span>${formatCurrency(order.total)}</span>
          <span class="${statusClass}">${order.status}</span>
        </div>
        <div class="order-details">
          <p>TOTAL</p>
          <p class="total">$${order.total.toFixed(2)}</p>
        </div>
      `;
      ordersContainer.appendChild(row);
    });
  }

  function formatCurrency(value) {
    return value.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
  }

  displayOrders(mockData);
};



// SLERP Animation example
function interpolate(a, b, t) {
  return a + t * (b - a);
}

const fromPoint = { x: 0, y: 0 };
const toPoint = { x: 100, y: 100 };

let t = 0;

function updateAnimation() {
  const newPoint = interpolate(fromPoint, toPoint, t);
  t += 0.01;

  requestAnimationFrame(updateAnimation);
}

updateAnimation();

