document.getElementById('orderForm').addEventListener('submit', function (e) {
  e.preventDefault();

  let orderId = Math.floor(Math.random() * 1000);
  let customerId = "C" + Math.floor(Math.random() * 100);
  let amount = parseFloat(document.querySelector('#amount').value);

  // Add order to list
  let orderElement = document.createElement('div');
  orderElement.classList.add('order-row');

  let status = "pending";
  if (amount > 100) {
    status = "completed";
  } else if (amount > 20 && amount <= 100) {
    status = "processing";
  } else {
    status = "default";
  }

  orderElement.innerHTML = `
    <div class="order-header">
      <span>${orderId}</span>
      <span>${customerId}</span>
      <span>$${amount.toFixed(2)}</span>
      <span class="status-${status}"">${status}</span>
    </div>
    <div class="order-details">
      <p>TOTAL</p>
      <p class="total">$${amount.toFixed(2)}</p>
    </div>
  `;

  document.getElementById('orders-container').appendChild(orderElement);

  // Highlight the order
  document.querySelectorAll('.order-row').forEach(el => el.style.boxShadow = '0 0 5px rgba(0,0,0,0.3)');
  setTimeout(() => {
    document.querySelectorAll('.order-row').forEach(el => el.style.boxShadow = '');
  }, 3000);
});

